<?php
namespace qqworld_collector\module\collecting\method; use qqworld_collector\lib; class strings extends lib { var $guid = 'string'; public function __construct() { add_filter( 'qqworld-collector-collecting-method-' . $this->guid, array($this, 'parse') ); } public function parse($value) { $random = explode('<!--s-->', $value); if (count($random) > 1) { $random = array_filter($random, array($this, 'is_not_empty')); foreach ($random as &$str) { $str = trim($str); } $value = $random[array_rand($random)]; } $value = apply_filters( 'qqworld-collector-collection-project-variable-filter', $value, 0 ); $results = array($value); return $results; } } ?>